from collections import deque


def is_escape_possible(blocked, source, target):
    BOUND = 20000
    blocked_set = {tuple(b) for b in blocked}

    def bfs(start, end):
        visited = {tuple(start)}
        queue = deque([tuple(start)])
        while queue:
            r, c = queue.popleft()
            if [r, c] == end or (r, c) == tuple(end):
                return True
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < 10**6 and 0 <= nc < 10**6 and (nr, nc) not in visited and (nr, nc) not in blocked_set:
                    if (nr, nc) == tuple(end):
                        return True
                    visited.add((nr, nc))
                    queue.append((nr, nc))
                    if len(visited) > BOUND:
                        return True
        return False

    if not bfs(source, target):
        return False
    if not bfs(target, source):
        return False
    return True

